            ReturnAbility = "Leap Back"
        },
        NormalDialogue = {
            Response = "*Haar!*... *Humph!*... You again... what do you seek?",
            Option2 = {
                Condition = {
                    Req1 = "blueGatesCheck1"
                },
                Response = "I remember our last encounter well. Your movements… they carried potential. But raw potential is meaningless without discipline. If you\'re willing to endure, I can help you awaken more of your inner gates.",
                Text = "Can you train me?",
                Type = "canUnlockBlueGates",
                Option1 = {
                    Response = "Even now, I wear weights on my body. Every step, every strike—burdened. This is how I\'ve trained, so that when I remove them… I surpass even my limits. If you can carry what I carry and still endure, then you\'re ready.",
                    Text = "What task?",
                    Option1 = {
                        Response = "I will place these training weights on you. They will test your stamina, your speed, and your willpower. Meet near The Dojo — *before time runs out*. Fail, and the opportunity slips away. Will you rise to this challenge?",
                        Text = "I can handle it.",
                        Option1 = {
                            Text = "I\'m ready.",
                            Type = "startBlueGatesQuest"
                        },
                        Option2 = {
                            Text = "Bye.",
                            Type = "Quit"
                        }
                    },
                    Option2 = {
                        Text = "Bye.",
                        Type = "Quit"
                    }
                },
                Option2 = {
                    Text = "I\'m weak.",
                    Type = "Quit"
                },
                Failed = {
                    Response = "Your fists are weak.",
                    Text = "...",
                    Type = "Quit"
                },
                FailedV1 = {
                    Response = "Your defense is weak.",
                    Text = "...",
                    Type = "Quit"
                },
                FailedV2 = {
                    Response = "I can tell you\'ve yet to grasp the basics of your inner gates. You must learn control before chasing power.",
                    Text = "...",
                    Type = "Quit"
                }
            },
            Option1 = {
                Text = "...",
                Type = "Quit"
            }
        },
        SuccessDialogue = {
            Response = "You\'ve done it… I\'m impressed. Not many can bear that weight and still move with purpose. You\'ve proven your resolve. Take this technique—it was once entrusted to me. But remember: power used without restraint will destroy you from within.",
            Option1 = {
                Text = "Thanks.",
                Type = "Quit"
            }
        },
        CompletedDialogue = {
            Response = "*Haar!*... Still standing tall, I see. That\'s good.",
            Option1 = {
                Text = "...",
                Type = "Quit"
            }
        },
        RetryDialogue = {
            Response = "Not everyone succeeds on their first attempt. But strength isn\'t measured by success—it\'s measured by how often you stand back up.",
            Option1 = {
                Response = "I see you still carry that fire in your eyes. Very well. Prove your spirit once more.",
                Text = "I want to retry.",
                Type = "startBlueGatesQuest"
            },
            Option2 = {
                Text = "It\'s hard...",
                Type = "Quit"
            }
        },
        CooldownDialogue = {
            Response = "You\'ve pushed yourself hard. Even steel needs time to cool. Return once your body has recovered — then, we try again.",
            Option1 = {
                Text = "Ok.",
                Type = "Quit"
